describe('Gnash mob skill',function()
 it('uses target HP with random percent fTP and resets enmity only after processed damage',function()
  local gnash=require('scripts/actions/mobskills/gnash');local move,process,random=xi.mobskills.mobPhysicalMove,xi.mobskills.processDamage,math.random;local params,damage,reset=nil,nil,nil;local mob={resetEnmity=function(_,target)reset=target end};local target={getHP=function()return 500 end,takeDamage=function(_,...)damage={...}end};xi.mobskills.mobPhysicalMove=function(_,_,_,_,v)params=v;return {damage=123,attackType=xi.attackType.PHYSICAL,damageType=xi.damageType.PIERCING}end;xi.mobskills.processDamage=function()return false end;math.random=function(min,max)assert(min==45 and max==55);return 50 end
  assert(gnash.onMobSkillCheck(target,mob,{})==0 and gnash.onMobWeaponSkill(mob,target,{},{})==123);assert(params.baseDamage==500 and params.numHits==1 and params.fTP[1]==.5 and params.fTP[2]==.5 and params.fTP[3]==.5 and params.attackType==xi.attackType.PHYSICAL and params.damageType==xi.damageType.PIERCING and params.shadowBehavior==xi.mobskills.shadowBehavior.IGNORE_SHADOWS and params.skipFSTR and params.skipPDIF and params.skipParry and params.skipGuard and params.skipBlock and damage==nil and reset==nil);xi.mobskills.processDamage=function()return true end;gnash.onMobWeaponSkill(mob,target,{},{})
  xi.mobskills.mobPhysicalMove,xi.mobskills.processDamage,math.random=move,process,random;assert(damage[1]==123 and damage[2]==mob and damage[3]==xi.attackType.PHYSICAL and damage[4]==xi.damageType.PIERCING and reset==target)
 end)
end)
